PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT (COUNT(DISTINCT ?monthTime) AS ?monthCount) WHERE {
  GRAPH <hydroturtle/quadica> {
    ?sensor a sosa:Sensor ;
      dct:identifier "BW_CKS022" .
    ?observation sosa:madeBySensor ?sensor ;
